INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27723$nota-0139$m27723$, $m27724$Training and Racing with a Power Meter.pdf$m27724$, $m27725$397$m27725$, $m27726$A Quadrant Analysis of Jeremiah's race shows that 21 percent of his ride was spent in Quadrant II, which represents slower cadence and higher force, and therefore we know that fatigue resistance of Type II fibers was a determining factor in his success... we can examine the amount of data in Quadrants III and IV, which represent nearly 75 percent of his ride. This confirms that Jeremiah did a very good job of pacing himself over the entire ride.$m27726$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27727$nota-0139$m27727$, $m27728$nota-0122$m27728$, $m27729$complementa$m27729$, $m27730$fornece um benchmark numérico específico para MTB ultraresistência, complementando o método geral de comparação treino-vs-prova (nota-0122)$m27730$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27731$nota-0146$m27731$, $m27732$Training and Racing with a Power Meter.pdf$m27732$, $m27733$472$m27733$, $m27734$Pedaling smoothness Commonly used for bilateral power-meter metrics. The mean power averaged across one crank cycle divided by the peak power applied during that cycle—e.g., Pavg/Ppeak=Pedal Smoothness... For example: Pavg=200W, Ppeak=1500, so PS=13 percent... A smoother pedal stroke would be: Pavg=350W, Ppeak=700W, so PS=50 percent.$m27734$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27735$nota-0146$m27735$, $m27736$Training and Racing with a Power Meter.pdf$m27736$, $m27737$473$m27737$, $m27738$Torque efficiency A metric commonly used for bilateral power meters in the Garmin ANT+ metrics. The sum of the positive power and the negative power over a single stroke divided by the positive power. For example: P+=150W, P-=30W. TE=100x(150+-30)/150= 100(120/150)=80% torque efficiency.$m27738$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27739$nota-0146$m27739$, $m27740$nota-0068$m27740$, $m27741$complementa$m27741$, $m27742$métricas bilaterais adicionais de qualidade de pedalada, complementares ao GPR/GPA/Kurtotic Index já registrados nas notas do Cap.7$m27742$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27743$nota-0147$m27743$, $m27744$Training and Racing with a Power Meter.pdf$m27744$, $m27745$472$m27745$, $m27746$Ppeak The peak power applied during a single pedal cycle. This is misnamed 'Pmax' in the ANT+ pedaling metrics and is seen in Garmin head units as Pmax. See Pmax for the correct definition of Pmax.$m27746$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27747$nota-0147$m27747$, $m27748$Training and Racing with a Power Meter.pdf$m27748$, $m27749$472$m27749$, $m27750$Pmax The maximal power that can be generated for a very short period of time over at least a full pedal revolution with both legs. Units are W or W/kg.$m27750$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27751$nota-0147$m27751$, $m27752$nota-0077$m27752$, $m27753$contradiz$m27753$, $m27754$alerta de nomenclatura: o 'Pmax' do modelo PDC (nota-0077, potência máxima sobre uma revolução completa de pedalada com as duas pernas) é um valor diferente do campo 'Pmax' que aparece em unidades Garmin/ANT+ (que na verdade é Ppeak, pico instantâneo de um único ciclo de pedalada)$m27754$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27755$nota-0150$m27755$, $m27756$Manual treinamento.pdf$m27756$, $m27757$22$m27757$, $m27758$Torque = Força × Braço de alavanca ... Potência = Torque × Velocidade Angular ... Subidas íngremes geralmente exigem elevado torque e baixa cadência. Contrarrelógios e terrenos planos normalmente apresentam torque moderado e elevada velocidade angular. Ambas as situações podem resultar na mesma potência.$m27758$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27759$nota-0151$m27759$, $m27760$Manual treinamento.pdf$m27760$, $m27761$24$m27761$, $m27762$Em intensidades moderadas, muitos ciclistas naturalmente selecionam cadências entre 80 e 95 rpm. Em esforços máximos, especialmente no sprint, valores superiores a 110 rpm são comuns. Já em subidas íngremes, cadências inferiores a 75 rpm podem representar a estratégia mais eficiente.$m27762$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27763$nota-0151$m27763$, $m27764$nota-0150$m27764$, $m27765$pre-requisito$m27765$, $m27766$usa a relação torque/velocidade angular/potência para explicar por que essas faixas de cadência variam por contexto$m27766$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27767$nota-0152$m27767$, $m27768$Manual treinamento.pdf$m27768$, $m27769$23$m27769$, $m27770$estudos utilizando pedais instrumentados e análise eletromiográfica mostraram que ciclistas experientes concentram a produção de força principalmente na fase descendente da pedalada... Quando atletas tentam aumentar deliberadamente a força durante a recuperação, frequentemente ocorre aumento da coativação muscular e do consumo energético, sem melhora proporcional da potência.$m27770$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27771$nota-0158$m27771$, $m27772$Manual treinamento.pdf$m27772$, $m27773$50$m27773$, $m27774$Embora exista relação entre frequência cardíaca e intensidade do exercício, essa relação não é perfeita. Temperatura, hidratação, altitude, fadiga, estresse psicológico e ingestão de cafeína representam apenas alguns fatores capazes de modificar essa resposta. Por essa razão, a frequência cardíaca deve sempre ser interpretada dentro de um contexto fisiológico mais amplo.$m27774$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27775$nota-0176$m27775$, $m27776$Manual treinamento.pdf$m27776$, $m27777$85$m27777$, $m27778$FTP não representa um limiar fisiológico. FTP corresponde a uma estimativa funcional da maior potência sustentável durante aproximadamente uma hora. Na maioria dos atletas treinados, encontra-se relativamente próximo ao MLSS. Entretanto: não mede lactato; não mede ventilação; não mede metabolismo. Mede desempenho.$m27778$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27779$nota-0176$m27779$, $m27780$nota-0174$m27780$, $m27781$pre-requisito$m27781$, $m27782$a comparação FTP≈MLSS depende da definição de MLSS estabelecida na nota-0174$m27782$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27783$nota-0176$m27783$, $m27784$nota-0019$m27784$, $m27785$complementa$m27785$, $m27786$complementa a definição operacional de FTP do Livro 1 (nota-0019) com a ressalva de que é uma medida de desempenho, não uma medida fisiológica direta$m27786$)
